/**
 * @title SystemVerilog Entry Example
 * @brief Basic IEEE 1800 Simulation Harness
 */
`timescale 1ns/1ps

module tb_hello_sv();
  initial begin
    $timeformat(-9, 2, " ns", 10);
    $display("===========================================");
    $display("[%0t] Hello Professional SystemVerilog!", $time);
    $display("===========================================");
    #10;
    $finish;
  end
endmodule

class sv_types_demo;
  // 四值邏輯 (0, 1, X, Z)
  logic [7:0] data = 8'hXZ;

  // 二值邏輯 (0, 1)
  bit [7:0] cnt = 8'hFF;

  // 強型別整數
  int result = 42;
  string name = "SoC_Verification";

  function void display_types();
    $display("Logic: %b, Bit: %b, String: %s", data, cnt, name);
  endfunction
endclass

int dyn[];
initial begin
  dyn = new[5];
  foreach(dyn[i]) dyn[i] = i*2;
  $display("Size=%0d", dyn.size());
end

int mem[int]; // key=int, value=int
initial begin
  mem[100] = 8'hAA;
  if(mem.exists(100)) $display("Found!");
end

class Packet;
  rand bit [7:0] addr;
  rand bit [31:0] data;

  function void display();
    $display("Addr=%0h Data=%0h", addr, data);
  endfunction
endclass

initial begin
  Packet p = new();
  p.randomize();
  p.display();
end

class eth_pkt;
  rand bit [15:0] length;
  rand bit [7:0]  payload[];

  constraint c_len {
    length inside {[64:1518]};
  }
  constraint c_payload {
    payload.size() == length;
  }
endclass

initial begin
  fork
    begin : thread_1
      #10 $display("Thread 1 done");
    end
    begin : thread_2
      #20 $display("Thread 2 done");
    end
  join_any
  $display("At least one thread done");
  disable fork;
end

interface bus_if(input logic clk);
  logic [7:0] addr;
  logic [31:0] data;
  logic wr_en, rd_en;

  modport master(output addr, data, wr_en, rd_en);
  modport slave(input addr, data, wr_en, rd_en);
endinterface

interface apb_if(input logic clk);
  logic [31:0] paddr, pwdata, prdata;
  logic pwrite, psel, penable;

  clocking drv_cb @(posedge clk);
    output paddr, pwdata, pwrite, psel, penable;
    input  prdata;
  endclocking

  clocking mon_cb @(posedge clk);
    input paddr, pwdata, prdata, pwrite, psel, penable;
  endclocking
endinterface

class cov_collector;
  covergroup cg @(posedge clk);
    cp_opcode: coverpoint opcode {
      bins add = {4'h0};
      bins sub = {4'h1};
      bins mul = {4'h2};
      bins others = default;
    }
    cp_size: coverpoint size {
      bins small = {[1:64]};
      bins large = {[65:256]};
    }
    cross_op_sz: cross cp_opcode, cp_size;
  endgroup
endclass

// 即時斷言
always @(posedge clk)
  assert (grant |-> req)
    else $error("Grant without request!");

// 並行斷言 (property)
property p_handshake;
  @(posedge clk)
  req |-> ##[1:3] ack;
endproperty
assert property (p_handshake);

