module my_design (
    input  logic clk,
    input  logic reset_n, // Active-low reset
    input  logic d1, 
    input  logic d2,
    output logic  q
);

    logic temp;

    always @(posedge clk) begin
      if (!reset_n)
        q <= 0;
      else begin
        // Blocking assignment (combinational style) mixed inside sequential block
        temp = d1 & d2;     
        q <= temp | (q << 1);  

        // Incrementing q again creates ambiguity in synthesis
        q = q + 1;    
      end
    end

endmodule

function logic func_and;
  input logic a, b;
  begin
    func_and = a & b;  // depends on both a and b
  end
endfunction

logic x, y, z;

always @* begin  // @* may miss x and y
  z = func_and(x, y);  
end

always_comb begin      // infers x and y
  z = func_and(x, y);
end

module data_selector_with_latch (
    input  wire a_in,
    input  wire b_in,
    input  wire sel,
    input  wire enable,
    output reg  data_out
);

    // This is the combinational part of the logic, a 2-to-1 mux
    wire mux_out;
    assign mux_out = sel ? a_in : b_in;

    // This is the sequential part (the latch) that will hold the value
    always_latch begin
        if (enable) begin
            data_out = mux_out;
        end      
    end

endmodule

module sync_counter_3bit (
    input  wire clk,
    input  wire reset_n, // Active-low reset
    output reg  [2:0] count
);

    // This is the sequential always block, triggered on a clock edge
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            // Asynchronous reset: sets the count to 0 when reset_n is low
            count <= 3'b000;
        end else begin
            // On the positive edge of the clock, increment the count
            count <= count + 1'b1;
        end
    end

endmodule

