// Nested class — represents a packet header
class Header;
    int id;

    function new(int id);
        this.id = id;
    endfunction
endclass

// Top-level class with a nested Header object
class Packet;
    int    addr;
    int    data;
    Header hdr;    // This is a handle to a Header object, not the object itself

    function new(int addr, int data, int id);
        hdr = new(id);       // Create a Header object and store its handle
        this.addr = addr;
        this.data = data;
    endfunction

    function void display(string name);
        $display("[%s] addr=0x%0h  data=0x%0h  id=%0d", name, addr, data, hdr.id);
    endfunction
endclass

module tb;
    Packet p1, p2;

    initial begin
        p1 = new(32'hface_cafe, 32'h1234_5678, 26);
        p1.display("p1");

        // Shallow copy: p2 gets its own addr and data, but shares p1's Header object
        p2 = new p1;
        p2.display("p2");

        // Modify p1's primitive members AND its nested hdr.id
        p1.addr    = 32'habcd_ef12;
        p1.data    = 32'h5a5a_5a5a;
        p1.hdr.id  = 17;        // This modifies the SHARED Header object

        p1.display("p1");

        // p2.addr and p2.data are unaffected (they were copied by value)
        // but p2.hdr.id HAS changed — p2 shares the same Header object as p1
        p2.display("p2");
    end
endmodule

class Packet;
    int    addr;
    int    data;
    Header hdr;

    function new(int addr, int data, int id);
        hdr = new(id);
        this.addr = addr;
        this.data = data;
    endfunction

    // Deep copy: copy primitive fields AND nested object fields individually
    function void copy(Packet p);
        this.addr   = p.addr;
        this.data   = p.data;
        this.hdr.id = p.hdr.id;   // Copy the value, not the handle
    endfunction

    function void display(string name);
        $display("[%s] addr=0x%0h  data=0x%0h  id=%0d", name, addr, data, hdr.id);
    endfunction
endclass

module tb;
    Packet p1, p2;

    initial begin
        p1 = new(32'hface_cafe, 32'h1234_5678, 26);
        p1.display("p1");

        // Deep copy: p2 must already exist before calling copy()
        p2 = new(1, 2, 3);    // Create p2 with placeholder values
        p2.copy(p1);           // Deep copy p1's contents into p2
        p2.display("p2");

        // Modify p1 including the nested hdr.id
        p1.addr   = 32'habcd_ef12;
        p1.data   = 32'h5a5a_5a5a;
        p1.hdr.id = 17;
        p1.display("p1");

        // p2 is now fully independent — none of its fields change
        p2.display("p2");
    end
endmodule

class SubHeader;
    int priority_level;
    function new(int p); this.priority_level = p; endfunction
endclass

class Header;
    int       id;
    SubHeader sub;

    function new(int id, int pri);
        this.id = id;
        sub = new(pri);
    endfunction

    // Copy all fields including the nested SubHeader
    function void copy(Header h);
        this.id                 = h.id;
        this.sub.priority_level = h.sub.priority_level;
    endfunction
endclass

class Packet;
    int    addr;
    int    data;
    Header hdr;

    function new(int addr, int data, int id, int pri);
        hdr = new(id, pri);
        this.addr = addr;
        this.data = data;
    endfunction

    function void copy(Packet p);
        this.addr = p.addr;
        this.data = p.data;
        this.hdr.copy(p.hdr);   // Delegate nested copy to Header's copy()
    endfunction

    function void display(string name);
        $display("[%s] addr=0x%0h  data=0x%0h  id=%0d  pri=%0d",
                 name, addr, data, hdr.id, hdr.sub.priority_level);
    endfunction
endclass

